      std::vector<Doc> docs;
      for (int i = 0; i < batch_size; i++) {
        docs.push_back(CreateTestDoc(batch * batch_size + i, 0));
      }
      auto write_result = collection->Insert(docs);
      ASSERT_TRUE(write_result);
      for (auto &s : write_result.value()) {
