Status SegmentImpl::open_fts_indexers(bool create) {
  if (!collection_schema_->has_fts_field()) {
    return Status::OK();
  }

  if (create) {
    auto block_id = allocate_block_id();
    auto fts_path = FileHelper::MakeFtsIndexPath(seg_path_, block_id);
    fts_indexer_ = FtsIndexer::CreateAndOpen(
        fts_path, collection_schema_->fts_fields(), true);
    if (!fts_indexer_) {
      return Status::InternalError("open_fts_indexers: create failed at [",
                                   fts_path, "]");
    }
    segment_meta_->add_persisted_block(
        BlockMeta{block_id, BlockType::FTS_INDEX, 0, 0, 0, {}});
  } else {
    for (const auto &block : segment_meta_->persisted_blocks()) {
      if (block.type() == BlockType::FTS_INDEX) {
        auto fts_path = FileHelper::MakeFtsIndexPath(seg_path_, block.id());
        fts_indexer_ = FtsIndexer::CreateAndOpen(
            fts_path, collection_schema_->fts_fields(), false,
            options_.read_only_);
        if (!fts_indexer_) {
          return Status::InternalError("open_fts_indexers: open failed at [",
                                       fts_path, "]");
        }
        break;
      }
    }
  }

  has_fts_ = (fts_indexer_ != nullptr);
  return Status::OK();
}

Status SegmentImpl::flush_fts_indexers() {
  if (!fts_indexer_) {
    return Status::OK();
  }
  return fts_indexer_->flush();
}

Status SegmentImpl::close_fts_indexers() {
  if (fts_indexer_) {
    fts_indexer_.reset();
  }
  return Status::OK();
}

Status SegmentImpl::insert_fts_indexer(Doc &doc) {
  if (!has_fts_) {
    return Status::OK();
  }
  for (const auto &field : collection_schema_->fts_fields()) {
    auto value = doc.get<std::string>(field->name());
    if (value.has_value()) {
      auto segment_doc_id = doc_ids_.size();
      auto s =
          fts_indexer_->insert(field->name(), segment_doc_id, value.value());
      if (!s.ok()) {
        return s;
      }
    }
  }
  return Status::OK();
}

Status SegmentImpl::dump_fts_indexers() {
  if (!has_fts_ || !fts_indexer_) {
    return Status::OK();
  }
  return fts_indexer_->seal_all();
}

fts::FtsColumnIndexerPtr SegmentImpl::get_fts_indexer(
    const std::string &field_name) const {
  if (!fts_indexer_) {
    return nullptr;
  }
  return fts_indexer_->get(field_name);
}

Result<std::vector<fts::FtsResult>> SegmentImpl::fts_search(
    const std::string &field_name, const fts::FtsAstNode &ast,
    const fts::FtsQueryParams &params) {
  auto indexer = get_fts_indexer(field_name);
  if (!indexer) {
    return tl::make_unexpected(
        Status::NotFound("FTS indexer not found: ", field_name));
  }

  auto ret = indexer->search(ast, params);
  if (!ret.has_value()) {
    return tl::make_unexpected(Status::InternalError(
        "FTS search failed: ", field_name, " ", ret.error().message()));
  }

  return std::move(ret.value());
}

Status SegmentImpl::create_fts_index(const std::string &column,
                                     const IndexParams::Ptr &index_params,
                                     SegmentMeta::Ptr *out_segment_meta,
                                     FtsIndexer::Ptr *out_fts_indexer) {
  auto fts_params = std::dynamic_pointer_cast<FtsIndexParams>(index_params);
  if (!fts_params) {
    return Status::InvalidArgument("create_fts_index: not FtsIndexParams");
  }

  auto field = collection_schema_->get_field(column);
  if (!field) {
    return Status::NotFound("create_fts_index: field not found: ", column);
  }

  if (field->index_params() != nullptr) {
    if (*field->index_params() == *index_params) {
      // Already indexed with same params, nothing to do.
      *out_segment_meta = std::make_shared<SegmentMeta>(*segment_meta_);
      *out_fts_indexer = fts_indexer_;
      return Status::OK();
    }
    if (field->index_params()->type() != index_params->type()) {
      return Status::InvalidArgument(
          "create_fts_index: field[", column, "] already has index type ",
          IndexTypeCodeBook::AsString(field->index_params()->type()));
    }
    // Same type but different params — will rebuild below.
  }

  auto new_segment_meta = std::make_shared<SegmentMeta>(*segment_meta_);
  new_segment_meta->remove_fts_index_block();

  auto block_id = allocate_block_id();
  auto new_fts_path = FileHelper::MakeFtsIndexPath(seg_path_, block_id);

  // Build a new schema that includes the new FTS field for the snapshot open.
  auto new_schema = std::make_shared<CollectionSchema>(*collection_schema_);
  new_schema->get_field(column)->set_index_params(index_params);

  FtsIndexer::Ptr new_fts_indexer;
  if (fts_indexer_) {
    // Snapshot existing fts DB, then open the copy with current schema.
    auto s = fts_indexer_->create_snapshot(new_fts_path);
    CHECK_RETURN_STATUS(s);

    new_fts_indexer = FtsIndexer::CreateAndOpen(
        new_fts_path, collection_schema_->fts_fields(), false);
  } else {
    // No existing fts DB — create a fresh one.
    new_fts_indexer =
        FtsIndexer::CreateAndOpen(new_fts_path, new_schema->fts_fields(), true);
  }
  if (!new_fts_indexer) {
    FileHelper::RemoveDirectory(new_fts_path);
    return Status::InternalError("create_fts_index: failed to open snapshot");
  }

  // If the field already exists in the snapshot (params change), remove it
  // first so we can recreate with the new params.
  if (new_fts_indexer->has_field(column)) {
    auto s = new_fts_indexer->remove_field_indexer(column);
    if (!s.ok()) {
      FileHelper::RemoveDirectory(new_fts_path);
      return s;
    }
  }

  {
    auto new_field_schema = std::make_shared<FieldSchema>(
        column, field->data_type(), field->nullable(), index_params);
    auto s = new_fts_indexer->create_field_indexer(*new_field_schema);
    if (!s.ok()) {
      FileHelper::RemoveDirectory(new_fts_path);
      return s;
    }
  }

  // Scan forward store and replay all existing documents.
  auto reader = scan({column});
  if (reader) {
    uint32_t seg_doc_id = 0;
    while (true) {
      auto batch = reader->Next();
      if (!batch.ok()) {
        FileHelper::RemoveDirectory(new_fts_path);
        return Status::InternalError("create_fts_index: scan failed: ",
                                     batch.status().message());
      }
      auto batch_value = batch.ValueOrDie();
      if (!batch_value) {
        break;
      }
      auto col_idx = batch_value->schema()->GetFieldIndex(column);
      if (col_idx < 0) {
        seg_doc_id += batch_value->num_rows();
        continue;
      }
      auto string_array = std::static_pointer_cast<arrow::StringArray>(
          batch_value->column(col_idx));
      for (int64_t i = 0; i < string_array->length(); ++i) {
        if (!string_array->IsNull(i)) {
          auto s = new_fts_indexer->insert(column, seg_doc_id,
                                           string_array->GetString(i));
          if (!s.ok()) {
            FileHelper::RemoveDirectory(new_fts_path);
            return s;
          }
        }
        seg_doc_id++;
      }
    }
  }

  // Seal the new field (flush + convert to BitPacked + drop side CFs).
  auto s = new_fts_indexer->seal(column);
  if (!s.ok()) {
    FileHelper::RemoveDirectory(new_fts_path);
    return s;
  }

  s = new_fts_indexer->flush();
  if (!s.ok()) {
    FileHelper::RemoveDirectory(new_fts_path);
    return s;
  }

  // Register the new block in segment meta.
  BlockMeta block;
  block.set_id(block_id);
  block.set_type(BlockType::FTS_INDEX);
  new_segment_meta->add_persisted_block(block);

  *out_segment_meta = new_segment_meta;
  *out_fts_indexer = new_fts_indexer;

  return Status::OK();
}

Status SegmentImpl::drop_fts_index(const std::string &column,
                                   SegmentMeta::Ptr *out_segment_meta,
                                   FtsIndexer::Ptr *out_fts_indexer) {
  auto field = collection_schema_->get_field(column);
  if (!field) {
    return Status::NotFound("drop_fts_index: field not found: ", column);
  }

  auto new_segment_meta = std::make_shared<SegmentMeta>(*segment_meta_);
  new_segment_meta->remove_fts_index_block();

  // Build a new schema without the FTS index on this column.
  auto new_schema = std::make_shared<CollectionSchema>(*collection_schema_);
  new_schema->get_field(column)->set_index_params(nullptr);

  if (!fts_indexer_) {
    *out_segment_meta = new_segment_meta;
    *out_fts_indexer = nullptr;
    return Status::OK();
  }

  // Check if other FTS fields remain after removal.
  bool has_other_fts = new_schema->has_fts_field();

  if (has_other_fts) {
    auto block_id = allocate_block_id();
    auto new_fts_path = FileHelper::MakeFtsIndexPath(seg_path_, block_id);

    // Snapshot and reopen without this field.
    auto s = fts_indexer_->create_snapshot(new_fts_path);
    CHECK_RETURN_STATUS(s);

    auto new_fts_indexer = FtsIndexer::CreateAndOpen(
        new_fts_path, collection_schema_->fts_fields(), false);
    if (!new_fts_indexer) {
      FileHelper::RemoveDirectory(new_fts_path);
      return Status::InternalError("drop_fts_index: failed to open snapshot");
    }

    s = new_fts_indexer->remove_field_indexer(column);
    CHECK_RETURN_STATUS(s);

    s = new_fts_indexer->flush();
    CHECK_RETURN_STATUS(s);

    BlockMeta block;
    block.set_id(block_id);
    block.set_type(BlockType::FTS_INDEX);
    new_segment_meta->add_persisted_block(block);

    *out_fts_indexer = new_fts_indexer;
  } else {
    // Last FTS field removed — no new indexer.
    *out_fts_indexer = nullptr;
  }

  *out_segment_meta = new_segment_meta;
  return Status::OK();
}

Status SegmentImpl::reload_fts_index(const CollectionSchema &schema,
                                     const SegmentMeta::Ptr &segment_meta,
                                     const FtsIndexer::Ptr &new_fts_indexer) {
  collection_schema_ = std::make_shared<CollectionSchema>(schema);
  segment_meta_ = segment_meta;

  if (fts_indexer_) {
    auto old_dir = fts_indexer_->working_dir();
    fts_indexer_ = new_fts_indexer;
    FileHelper::RemoveDirectory(old_dir);
  } else {
    fts_indexer_ = new_fts_indexer;
  }

  has_fts_ = (fts_indexer_ != nullptr);
  fresh_persist_block_offset();

  return Status::OK();
}

Status CollectionImpl::Optimize(const OptimizeOptions &options) {
  CHECK_COLLECTION_READONLY_RETURN_STATUS;

  std::lock_guard lock(schema_handle_mtx_);
  // when optimizing, schema operations(include another optimize) are not
  // allowed

  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);

  std::vector<Segment::Ptr> persist_segments;

  {
    // forbidden writing for a while
    std::lock_guard write_lock(write_mtx_);

    if (writing_segment_->doc_count() != 0) {
      // flush and create new segment
      auto s = switch_to_new_segment_for_writing();
      if (!s.ok()) {
        return s;
      }
    }

    persist_segments =
        get_all_persist_segments();  // will not return writing segment
    // after leave this scope, writing action is allowed
  }

  if (persist_segments.size() == 0) {
    // no need to optimize
    return Status::OK();
  }

  // build segment compact task
  auto delete_store_clone = delete_store_->clone();
  auto tasks =
      build_compact_task(schema_, persist_segments, options.concurrency_,
                         delete_store_clone->make_filter());

  // execute segment compact task
  auto s = execute_compact_task(tasks);
  CHECK_RETURN_STATUS(s);

  {
    // forbidden writing for updating version
    // writing action may trigger updating version where confict occurs
    std::lock_guard write_lock(write_mtx_);

    Version new_version = version_manager_->get_current_version();

    for (auto &task : tasks) {
      auto task_info = task->task_info();

      if (std::holds_alternative<CompactTask>(task_info)) {
        auto compact_task = std::get<CompactTask>(task_info);

        // 0. check if has output segment meta
        if (compact_task.output_segment_meta_) {
          // 1. rename built tmp segments
          auto tmp_segment_id = compact_task.output_segment_id_;
          auto tmp_segment_path =
              FileHelper::MakeTempSegmentPath(path_, tmp_segment_id);

          auto new_segment_id = allocate_segment_id();
          auto new_segment_path =
              FileHelper::MakeSegmentPath(path_, new_segment_id);

          if (!FileHelper::MoveDirectory(tmp_segment_path, new_segment_path)) {
            return Status::InternalError("move segment directory failed");
          }

          // update output_segment_meta_'s segment id
          compact_task.output_segment_meta_->set_id(new_segment_id);

          s = new_version.add_persisted_segment_meta(
              compact_task.output_segment_meta_);
          CHECK_RETURN_STATUS(s);
          new_version.set_next_segment_id(segment_id_allocator_.load());
        }

        for (auto input_segment : compact_task.input_segments_) {
          s = new_version.remove_persisted_segment_meta(input_segment->id());
          CHECK_RETURN_STATUS(s);
        }
      } else if (std::holds_alternative<CreateVectorIndexTask>(task_info)) {
        auto create_index_task = std::get<CreateVectorIndexTask>(task_info);
        s = new_version.update_persisted_segment_meta(
            create_index_task.output_segment_meta_);
        CHECK_RETURN_STATUS(s);
      }
    }

    // 2. update version
    s = version_manager_->apply(new_version);
    CHECK_RETURN_STATUS(s);

    // 3. persist version
    s = version_manager_->flush();
    CHECK_RETURN_STATUS(s);

    // 4. remove old segments or block
    for (auto &task : tasks) {
      auto task_info = task->task_info();

      if (std::holds_alternative<CompactTask>(task_info)) {
        auto compact_task = std::get<CompactTask>(task_info);

        if (compact_task.output_segment_meta_) {
          auto new_segment =
              Segment::Open(path_, *schema_, *compact_task.output_segment_meta_,
                            id_map_, delete_store_, version_manager_,
                            SegmentOptions{true, options_.enable_mmap_});
          if (!new_segment.has_value()) {
            return new_segment.error();
          }
          s = segment_manager_->add_segment(new_segment.value());
          CHECK_RETURN_STATUS(s);
        }

        for (auto input_segment : compact_task.input_segments_) {
          s = segment_manager_->destroy_segment(input_segment->id());
          CHECK_RETURN_STATUS(s);
        }
      } else if (std::holds_alternative<CreateVectorIndexTask>(task_info)) {
        auto create_index_task = std::get<CreateVectorIndexTask>(task_info);

        s = create_index_task.input_segment_->reload_vector_index(
            *schema_, create_index_task.output_segment_meta_,
            create_index_task.output_vector_indexers_,
            create_index_task.output_quant_vector_indexers_);
        CHECK_RETURN_STATUS(s);
      }
    }
  }

  return Status::OK();
}

std::vector<SegmentTask::Ptr> CollectionImpl::build_compact_task(
    const CollectionSchema::Ptr &schema,
    const std::vector<Segment::Ptr> &segments, int concurrency,
    const IndexFilter::Ptr filter) {
  std::vector<SegmentTask::Ptr> tasks;
  if (segments.empty()) return tasks;

  bool rebuild = false;
  size_t current_doc_count = 0;
  size_t current_actual_doc_count = 0;
  for (auto &segment : segments) {
    current_doc_count += segment->doc_count();
    current_actual_doc_count += segment->doc_count(filter);
  }
  if (current_actual_doc_count <
      current_doc_count * (1 - COMPACT_DELETE_RATIO_THRESHOLD)) {
    // if delete ratio is large enough, rebuild
    rebuild = true;
  }

  auto max_doc_count_per_segment = schema->max_doc_count_per_segment();

  std::vector<Segment::Ptr> current_group;
  current_doc_count = 0;
  current_actual_doc_count = 0;

  for (const auto &seg : segments) {
    uint64_t doc_count = seg->doc_count();
    uint64_t actual_doc_count = seg->doc_count(filter);

    if (!current_group.empty()) {
      SegmentTask::Ptr task;
      bool skip_task{false};
      if (rebuild) {
        if (current_actual_doc_count + actual_doc_count >
            max_doc_count_per_segment) {
          // only create SegmentCompactTask when rebuild=true
          task = SegmentTask::CreateCompactTask(
              CompactTask{path_, schema, current_group,
                          allocate_segment_id_for_tmp_segment(), filter,
                          !options_.enable_mmap_, concurrency});
        }
      } else {
        if (current_doc_count + doc_count > max_doc_count_per_segment) {
          // check current_group size
          if (current_group.size() == 1) {
            task =
                SegmentTask::CreateCreateVectorIndexTask(CreateVectorIndexTask{
                    current_group[0], "", nullptr, concurrency});
            skip_task = current_group[0]->all_vector_index_ready();
          } else {
            task = SegmentTask::CreateCompactTask(
                CompactTask{path_, schema, current_group,
                            allocate_segment_id_for_tmp_segment(), nullptr,
                            !options_.enable_mmap_, concurrency});
          }
        }
      }

      if (task) {
        current_group.clear();
        current_doc_count = 0;
        current_actual_doc_count = 0;
        if (!skip_task) {
          tasks.push_back(task);
        }
      }
    }

    current_group.push_back(seg);
    current_doc_count += doc_count;
    current_actual_doc_count += actual_doc_count;
  }

  if (current_group.size() > 0) {
    SegmentTask::Ptr task;
    if (current_group.size() == 1 && !rebuild) {
      task = SegmentTask::CreateCreateVectorIndexTask(
          CreateVectorIndexTask{current_group[0], "", nullptr, concurrency});
    } else {
      task = SegmentTask::CreateCompactTask(CompactTask{
          path_, schema, current_group, allocate_segment_id_for_tmp_segment(),
          rebuild ? filter : nullptr, !options_.enable_mmap_, concurrency});
    }
    tasks.push_back(task);
  }

  return tasks;
}

Status CollectionImpl::execute_compact_task(
    std::vector<SegmentTask::Ptr> &tasks) const {
  Status s;
  for (auto &task : tasks) {
    s = SegmentHelper::Execute(task);
    if (!s.ok()) {
      return s;
    }
  }

  return Status::OK();
}

